	for _, e := range merged {
		if q.eval(e) {
			matches = append(matches, e)
		}
	}
	return QueryOutput{
		Status:  "ok",
		Query:   expr,
		Matches: len(matches),
		Entries: matches,
	}, nil
}

type condition struct {
	field string
	op    string
	sval  string
	fval  float64
	isNum bool
}

type node interface {
	eval(e types.TimelineEntry) bool
}

type conditionNode struct {
	condition condition
}

type notNode struct {
	child node
}

type andNode struct {
	children []node
}

type orNode struct {
	children []node
}

func (c conditionNode) eval(e types.TimelineEntry) bool {
	return c.condition.eval(e)
}

func (n notNode) eval(e types.TimelineEntry) bool {
	return !n.child.eval(e)
}

func (a andNode) eval(e types.TimelineEntry) bool {
	for _, child := range a.children {
		if !child.eval(e) {
			return false
		}
	}
	return true
}

func (o orNode) eval(e types.TimelineEntry) bool {
	for _, child := range o.children {
		if child.eval(e) {
			return true
		}
	}
	return false
}

func (c condition) eval(e types.TimelineEntry) bool {
	switch c.field {
	case "step":
		return compareNum(float64(e.Step), c)
	case "epoch":
		return compareNum(float64(e.Epoch), c)
	case "loss":
		return ptrCompareNum(e.Loss, c)
	case "lr":
		return ptrCompareNum(e.Lr, c)
	case "grad_norm":
		return ptrCompareNum(e.GradNorm, c)
	case "acc":
		return ptrCompareNum(e.Acc, c)
	case "event":
		return compareStr(e.Event, c)
	case "ts":
		return compareTs(e.Ts, c)
	}
	return false
}

func compareNum(val float64, c condition) bool {
	if !c.isNum {
		return false
	}
	switch c.op {
	case ">":
		return val > c.fval
	case "<":
		return val < c.fval
	case ">=":
		return val >= c.fval
	case "<=":
		return val <= c.fval
	case "==":
		return absFloat(val-c.fval) <= 1e-9
	case "!=":
		return absFloat(val-c.fval) > 1e-9
	}
	return false
}

func ptrCompareNum(p *float64, c condition) bool {
	if p == nil {
		return false
	}
	return compareNum(*p, c)
}

func compareStr(val string, c condition) bool {
	if c.isNum {
		return false
	}
	switch c.op {
	case "==":
		return val == c.sval
	case "!=":
		return val != c.sval
	}
	return false
}

func compareTs(val string, c condition) bool {
	lt, err := time.Parse(time.RFC3339, val)
	if err != nil {
		return false
	}
	rt, err := time.Parse(time.RFC3339, c.sval)
	if err != nil {
		return false
	}
	switch c.op {
	case ">":
		return lt.After(rt)
	case "<":
		return lt.Before(rt)
	case ">=":
		return lt.After(rt) || lt.Equal(rt)
	case "<=":
		return lt.Before(rt) || lt.Equal(rt)
	case "==":
		return lt.Equal(rt)
	case "!=":
		return !lt.Equal(rt)
	}
	return false
}

func absFloat(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

type parser struct {
	tokens []string
	pos    int
}

func parseQuery(expr string) (node, error) {
	tokens, err := tokenizeQuery(expr)
	if err != nil {
		return nil, err
	}
	if len(tokens) == 0 {
		return nil, fmt.Errorf("empty query")
	}
	p := &parser{tokens: tokens}
	n, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if p.pos != len(p.tokens) {
		return nil, fmt.Errorf("unexpected token: %s", p.current())
	}
	return n, nil
}

func (p *parser) current() string {
	if p.pos < len(p.tokens) {
		return p.tokens[p.pos]
	}
	return ""
}

func (p *parser) match(tok string) bool {
	if p.current() == tok {
		p.pos++
		return true
	}
	return false
}

func (p *parser) parseOr() (node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for {
		if !p.match("OR") {
			break
		}
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		if or, ok := left.(orNode); ok {
			or.children = append(or.children, right)
			left = or
		} else {
			left = orNode{children: []node{left, right}}
		}
	}
	return left, nil
}

func (p *parser) parseAnd() (node, error) {
	left, err := p.parseNot()
	if err != nil {
		return nil, err
	}
	for {
		if !p.match("AND") {
			break
		}
		right, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		if and, ok := left.(andNode); ok {
			and.children = append(and.children, right)
			left = and
		} else {
			left = andNode{children: []node{left, right}}
		}
	}
	return left, nil
}

func (p *parser) parseNot() (node, error) {
	if p.match("NOT") {
		child, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		return notNode{child: child}, nil
	}
	return p.parseAtom()
}

func (p *parser) parseAtom() (node, error) {
	if p.match("(") {
		expr, err := p.parseOr()
		if err != nil {
			return nil, err
		}
		if !p.match(")") {
			return nil, fmt.Errorf("missing closing parenthesis")
		}
		return expr, nil
	}
	cond, err := p.parseCondition()
	if err != nil {
		return nil, err
	}
	return conditionNode{condition: cond}, nil
}

func (p *parser) parseCondition() (condition, error) {
	if p.pos+2 >= len(p.tokens) {
		return condition{}, fmt.Errorf("invalid query syntax")
	}

	field := p.tokens[p.pos]
	op := p.tokens[p.pos+1]
	valueTok := p.tokens[p.pos+2]

	validFields := map[string]bool{"step": true, "epoch": true, "loss": true, "lr": true, "grad_norm": true, "acc": true, "event": true, "ts": true}
	if !validFields[field] {
		return condition{}, fmt.Errorf("unknown field: %s", field)
	}
	validOps := map[string]bool{">": true, "<": true, ">=": true, "<=": true, "==": true, "!=": true}
	if !validOps[op] {
		return condition{}, fmt.Errorf("invalid operator: %s", op)
	}

	c := condition{field: field, op: op, sval: valueTok}
	if field == "event" {
		if op != "==" && op != "!=" {
			return condition{}, fmt.Errorf("type mismatch: event only supports == or !=")
		}
		if !isQuotedString(valueTok) {
			return condition{}, fmt.Errorf("type mismatch: event requires string value")
		}
		c.sval = unquote(valueTok)
		return c, p.pos + 3, nil
	}
	if field == "ts" {
		if _, err := time.Parse(time.RFC3339, unquote(valueTok)); err != nil {
			return condition{}, fmt.Errorf("invalid timestamp: %s", valueTok)
		}
		c.sval = unquote(valueTok)
		return c, p.pos + 3, nil
	}
	num, err := strconv.ParseFloat(valueTok, 64)
	if err != nil {
		return condition{}, fmt.Errorf("type mismatch: %s requires numeric value", field)
	}
	c.fval = num
	c.isNum = true
	return c, p.pos + 3, nil
}

func tokenizeQuery(s string) ([]string, error) {
	var tokens []string
	i := 0
	for i < len(s) {
		ch := s[i]
		if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
			i++
			continue
		}
		if ch == '"' {
			j := i + 1
			for j < len(s) && s[j] != '"' {
				j++
			}
			if j >= len(s) {
				return nil, fmt.Errorf("unterminated string")
			}
			tokens = append(tokens, s[i:j+1])
			i = j + 1
			continue
		}
		if ch == '(' || ch == ')' {
			tokens = append(tokens, string(ch))
			i++
			continue
		}
		if strings.HasPrefix(s[i:], ">=") || strings.HasPrefix(s[i:], "<=") || strings.HasPrefix(s[i:], "==") || strings.HasPrefix(s[i:], "!=") {
			tokens = append(tokens, s[i:i+2])
			i += 2
			continue
		}
		if ch == '>' || ch == '<' {
			tokens = append(tokens, string(ch))
			i++
			continue
		}
		j := i
		for j < len(s) {
			c := s[j]
			if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '>' || c == '<' || c == '=' || c == '!' || c == '"' || c == '(' || c == ')' {
				break
			}
			j++
		}
		if j == i {
			return nil, fmt.Errorf("invalid character in query: %c", ch)
		}
		tokens = append(tokens, s[i:j])
		i = j
	}
	return tokens, nil
}

func isQuotedString(s string) bool {
	return len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"'
}

func unquote(s string) string {
	if isQuotedString(s) {
		return s[1 : len(s)-1]
	}
	return s
}
